    'prog.res_all': { ko: '30개 레벨을 전부 깼어요. 진짜 프로그래머!', en: 'All 30 levels cleared. A real programmer!', ja: '30レベル全クリア。本物のプログラマー！', zh: '30 关全部通关，真正的程序员！', hi: 'सभी 30 स्तर पार। असली प्रोग्रामर!', vi: 'Qua hết 30 màn. Lập trình viên thứ thiệt!' },
