    'prog.res_over': { ko: '실행 횟수를 다 썼어요. 여기까지가 기록으로 남아요.', en: 'You used all your runs. This is your record.', ja: '実行回数を使い切りました。ここまでが記録です。', zh: '运行次数用完了。成绩记录到这里。', hi: 'सारे रन खत्म। यहाँ तक का रिकॉर्ड दर्ज हुआ।', vi: 'Đã dùng hết lượt chạy. Thành tích ghi đến đây.' },
    'prog.res_here': { ko: '여기까지가 기록으로 남아요. 다음엔 더 멀리!', en: 'This is your record for now. Go further next time!', ja: 'ここまでが記録に残ります。次はもっと遠くへ！', zh: '成绩记录到这里。下次走得更远！', hi: 'यहाँ तक का रिकॉर्ड दर्ज हुआ। अगली बार और आगे!', vi: 'Thành tích ghi đến đây. Lần sau đi xa hơn nhé!' },
