    'reach.timeout_take': { ko: '{name} 제한시간 {t}초 안에 손끝이 목표에 닿지 못했어요. 관절 힌트를 써 보세요.', en: 'The tip didn\'t reach the target within {name}\'s {t}-second limit. Try the joint hint.', ja: '{name}の制限時間{t}秒内に手先が目標に届きませんでした。関節ヒントを使ってみて。', zh: '{name}限时 {t} 秒内手尖没够到目标。试试关节提示。', hi: '{name} की {t} सेकंड सीमा में सिरा लक्ष्य तक नहीं पहुँचा। जोड़ संकेत आज़माओ।', vi: 'Đầu tay chưa chạm mục tiêu trong {t} giây của {name}. Thử gợi ý khớp xem.' },
