    'reach.lv26.take': { ko: '굴뚝을 오른 뒤 천장 밑을 기어 <b>좁은 주머니</b>로 내려갔어요.', en: 'Up the chimney, crawl under the ceiling, down into a <b>tight pocket</b>.', ja: '煙突を上り、天井の下をはって<b>せまいポケット</b>に下りました。', zh: '爬上烟囱，贴着天花板爬行，落进<b>狭小的口袋</b>。', hi: 'चिमनी चढ़कर छत के नीचे रेंगते हुए <b>तंग जेब</b> में उतरे।', vi: 'Leo ống khói, bò dưới trần rồi hạ vào <b>túi hẹp</b>.' },
    'reach.lv27.sub': { ko: '관절 7개 · 3단 뱀길', en: '7 joints · Three-step snake', ja: '関節7 · 3段ヘビ道', zh: '7 关节 · 三层蛇形路', hi: '7 जोड़ · तीन सीढ़ी साँप-राह', vi: '7 khớp · Đường rắn ba tầng' },
