    'reach.lv27.take': { ko: '세 단을 꺾는 뱀길. 관절 일곱을 <b>차례로</b> 맞춰야 통과해요.', en: 'A snake path with three turns. Set all seven joints <b>in order</b>.', ja: '3回曲がるヘビ道。7つの関節を<b>順番に</b>合わせて通ります。', zh: '转三次的蛇形路。七个关节要<b>依次</b>调好。', hi: 'तीन मोड़ वाली साँप-राह। सातों जोड़ <b>क्रम से</b> सेट करने होंगे।', vi: 'Đường rắn ba khúc. Phải chỉnh bảy khớp <b>theo thứ tự</b>.' },
    'reach.lv28.sub': { ko: '관절 7개 · 좁은 갈고리', en: '7 joints · Tight hook', ja: '関節7 · せまいフック', zh: '7 关节 · 窄钩', hi: '7 जोड़ · तंग हुक', vi: '7 khớp · Móc hẹp' },
