    'build.tut1.s4': { ko: '라인이 이어졌어요. <b>가동</b>을 눌러요', en: 'The line is connected. Press <b>Run</b>', ja: 'ラインがつながりました。<b>稼働</b>を押そう', zh: '生产线接好了。按<b>开机</b>', hi: 'लाइन जुड़ गई। <b>चलाओ</b> दबाओ', vi: 'Dây chuyền đã nối. Bấm <b>Chạy</b>' },
    'build.tut2.s1': { ko: '이 칸이 <b>위로</b> 놓였어요 — 상자가 되돌아가요. <b>지우개</b>를 골라요', en: 'This cell points <b>up</b> — boxes go back. Pick the <b>eraser</b>', ja: 'このマスが<b>上向き</b>です — 箱が戻ってしまう。<b>消しゴム</b>を選ぼう', zh: '这格朝<b>上</b>——箱子会倒回去。选<b>橡皮</b>', hi: 'यह सेल <b>ऊपर</b> है — डिब्बे लौट जाते हैं। <b>रबर</b> चुनो', vi: 'Ô này hướng <b>lên</b> — hộp quay ngược. Chọn <b>tẩy</b>' },
