    // ── 지어라 레벨 문구(30) — 한국어 원본은 build-cari.html 의 LEVELS(= tmp/_build-levels.mjs). 생성: tmp/_build-i18n-apply.mjs ──
    'build.lv1.name': { ko: '직선 라인', en: 'Straight line', ja: '直線ライン', zh: '直线', hi: 'सीधी लाइन', vi: 'Đường thẳng' },
    'build.lv1.goal': { ko: '생산기 상자를 <b>컨베이어</b>로 아래 <b>출고함</b>까지 이어라', en: 'Connect the boxes to the <b>bin</b> below with <b>conveyors</b>', ja: '生産機の箱を<b>コンベア</b>で下の<b>出荷箱</b>までつなげ', zh: '用<b>传送带</b>把箱子送到下方的<b>出货箱</b>', hi: '<b>कन्वेयर</b> से डिब्बों को नीचे के <b>बिन</b> तक पहुँचाओ', vi: 'Nối hộp tới <b>thùng</b> bên dưới bằng <b>băng chuyền</b>' },
    'build.lv1.take': { ko: '컨베이어만 깔았는데 상자가 <b>알아서</b> 흘러 출고됐어요 — 이게 자동 라인!', en: 'Just conveyors, and the boxes shipped <b>on their own</b> — an automated line!', ja: 'コンベアを敷いただけで箱が<b>ひとりでに</b>流れて出荷された — これが自動ライン！', zh: '只是铺了传送带，箱子就<b>自己</b>流出去了——这就是自动线！', hi: 'सिर्फ़ कन्वेयर, और डिब्बे <b>अपने आप</b> चले गए — ऑटो लाइन!', vi: 'Chỉ băng chuyền mà hộp <b>tự</b> chạy ra — dây chuyền tự động!' },
    'build.lv2.name': { ko: '모퉁이', en: 'Corner', ja: '曲がり角', zh: '拐角', hi: 'मोड़', vi: 'Góc rẽ' },
    'build.lv2.goal': { ko: '함이 옆에 있다 — <b>꺾어서</b> 이어라', en: 'The bin is off to the side — <b>turn</b> the line', ja: '箱が横にある — <b>曲げて</b>つなげ', zh: '箱子在旁边——<b>拐弯</b>接过去', hi: 'बिन बगल में है — लाइन <b>मोड़ो</b>', vi: 'Thùng ở bên cạnh — <b>rẽ</b> để nối' },
    'build.lv3.name': { ko: '벽 돌아가기', en: 'Around the wall', ja: '壁を回る', zh: '绕过墙', hi: 'दीवार के चारों ओर', vi: 'Vòng qua tường' },
    'build.lv3.goal': { ko: '<b>벽</b>은 못 놓는 칸이다 — 돌아서 가라', en: 'You can’t build on a <b>wall</b> — go around', ja: '<b>壁</b>には置けない — 回り道しろ', zh: '<b>墙</b>上不能放——绕过去', hi: '<b>दीवार</b> पर नहीं रख सकते — घूमकर जाओ', vi: 'Không đặt lên <b>tường</b> được — đi vòng' },
    'build.lv4.name': { ko: '두 색 분류', en: 'Two colors', ja: '2色仕分け', zh: '两色分拣', hi: 'दो रंग', vi: 'Hai màu' },
    'build.lv4.goal': { ko: '<b>빨강 센서</b>로 빨강→오른쪽 함, 파랑→아래 함으로 갈라라', en: 'Use the <b>red sensor</b>: red → right bin, blue → bottom bin', ja: '<b>赤センサー</b>で赤→右の箱、青→下の箱に分けろ', zh: '用<b>红色传感器</b>：红→右箱，蓝→下箱', hi: '<b>लाल सेंसर</b> से लाल→दायाँ बिन, नीला→नीचे का बिन', vi: 'Dùng <b>cảm biến đỏ</b>: đỏ → thùng phải, xanh → thùng dưới' },
    'build.lv4.take': { ko: '센서 하나가 <b>빨강/파랑</b>을 스스로 갈라 보냈어요 — 판단하는 라인!', en: 'One sensor sorted <b>red/blue</b> on its own — a line that decides!', ja: 'センサー1つが<b>赤/青</b>を自分で分けて送った — 判断するライン！', zh: '一个传感器自己把<b>红/蓝</b>分开了——会判断的生产线！', hi: 'एक सेंसर ने <b>लाल/नीला</b> ख़ुद बाँट दिया — फ़ैसला करने वाली लाइन!', vi: 'Một cảm biến tự tách <b>đỏ/xanh</b> — dây chuyền biết quyết định!' },
    'build.lv5.name': { ko: '꺾이는 쪽이 정해져 있다', en: 'The turn side is fixed', ja: '曲がる側は決まっている', zh: '拐向是固定的', hi: 'मुड़ने की दिशा तय है', vi: 'Bên rẽ đã cố định' },
    'build.lv5.goal': { ko: '센서는 자기 색을 <b>진행 방향의 왼쪽</b>으로만 꺾는다 — 빨강 함이 반대쪽이면?', en: 'A sensor turns its color only to the <b>left of travel</b> — what if the red bin is on the other side?', ja: 'センサーは自分の色を<b>進行方向の左</b>にしか曲げない — 赤の箱が反対側なら？', zh: '传感器只把自己的颜色拐向<b>行进方向的左侧</b>——红箱在另一边怎么办？', hi: 'सेंसर अपना रंग सिर्फ़ <b>चलने की दिशा के बाएँ</b> मोड़ता है — लाल बिन दूसरी तरफ़ हो तो?', vi: 'Cảm biến chỉ rẽ màu của nó sang <b>bên trái hướng đi</b> — thùng đỏ ở phía bên kia thì sao?' },
    'build.lv6.name': { ko: '고장 난 라인', en: 'Broken line', ja: '故障したライン', zh: '坏掉的生产线', hi: 'टूटी लाइन', vi: 'Dây chuyền hỏng' },
    'build.lv6.goal': { ko: '누가 깔아둔 라인이 <b>어딘가 틀렸다</b> — 찾아서 고쳐라', en: 'Someone’s line is <b>wrong somewhere</b> — find it and fix it', ja: '誰かが敷いたラインが<b>どこか間違っている</b> — 見つけて直せ', zh: '别人铺的线<b>哪里错了</b>——找出来修好', hi: 'किसी की बिछाई लाइन <b>कहीं ग़लत</b> है — ढूँढो और ठीक करो', vi: 'Dây chuyền ai đó đặt <b>sai ở đâu đó</b> — tìm và sửa' },
    'build.lv7.name': { ko: '세 색', en: 'Three colors', ja: '3色', zh: '三色', hi: 'तीन रंग', vi: 'Ba màu' },
