    'build.lv10.goal': { ko: '벽에 <b>문이 하나</b>뿐이다 — 두 줄 다 그 문으로', en: 'The wall has <b>one door</b> — both lines must go through it', ja: '壁に<b>扉が1つ</b>だけ — 2本とも通せ', zh: '墙上<b>只有一扇门</b>——两条线都要走它', hi: 'दीवार में <b>एक ही दरवाज़ा</b> है — दोनों लाइनें उसी से', vi: 'Tường chỉ có <b>một cửa</b> — cả hai dây phải đi qua đó' },
