    'build.lv14.goal': { ko: '문이 <b>둘</b>이다 — 색마다 자기 문으로', en: 'There are <b>two</b> doors — each color takes its own', ja: '扉が<b>2つ</b> — 色ごとに自分の扉へ', zh: '有<b>两扇</b>门——每种颜色走自己的门', hi: '<b>दो</b> दरवाज़े हैं — हर रंग अपने दरवाज़े से', vi: 'Có <b>hai</b> cửa — mỗi màu một cửa riêng' },
    'build.lv15.name': { ko: '고집 센 센서', en: 'Stubborn sensor', ja: '頑固なセンサー', zh: '固执的传感器', hi: 'ज़िद्दी सेंसर', vi: 'Cảm biến cứng đầu' },
