    'build.lv17.name': { ko: '아래에서 올려 넣기', en: 'Feed from below', ja: '下から入れる', zh: '从下方送入', hi: 'नीचे से ऊपर', vi: 'Đưa từ dưới lên' },
    'build.lv17.goal': { ko: '두 함 다 <b>아래에서만</b> 들어간다 — 그런데 센서는 파랑뿐', en: 'Both bins open <b>only from below</b> — and you only have a blue sensor', ja: '2つの箱は<b>下からしか</b>入れない — しかもセンサーは青だけ', zh: '两个箱都<b>只能从下方</b>进入——而传感器只有蓝色', hi: 'दोनों बिन <b>सिर्फ़ नीचे से</b> खुलते हैं — और सेंसर सिर्फ़ नीला', vi: 'Cả hai thùng <b>chỉ vào từ dưới</b> — mà chỉ có cảm biến xanh' },
