    'build.lv18.goal': { ko: '빨강 함이 <b>위쪽</b>에 있다 — 내려갔다가 올라와라', en: 'The red bin is <b>up top</b> — go down, then come back up', ja: '赤の箱は<b>上</b>にある — 下りてから上がれ', zh: '红箱在<b>上方</b>——先下去再上来', hi: 'लाल बिन <b>ऊपर</b> है — नीचे जाकर वापस ऊपर आओ', vi: 'Thùng đỏ ở <b>phía trên</b> — đi xuống rồi quay lên' },
    'build.lv19.name': { ko: '두 줄이 한 색을 나눈다', en: 'Two lines share a color', ja: '2本が1色を共有', zh: '两条线共用一色', hi: 'दो लाइनें एक रंग साझा', vi: 'Hai dây chung một màu' },
